import { Box, IconButton, Link } from "@chakra-ui/react";
import { useMemo } from "react";
import { LANGFUSE_DOCS_URL } from "../constants";
import { ExternalLink, Icon } from "../Icon";
import { Tooltip } from "../Tooltip";
import type { Conversation } from "../types";

interface LangfuseSessionButtonProps {
  conversationList: Conversation[];
  sessionId: string;
}

const deriveSessionUrlFromTraceUrl = (traceUrl: string | undefined, senderId: string) => {
  if (!traceUrl) {
    return undefined;
  }

  // Langfuse cloud examples:
  // - /project/<id>/traces/<trace_id>
  // - /project/<id>/trace/<trace_id>
  return traceUrl
    .replace(/\/traces\/[^/?#]+/i, `/sessions/${senderId}`)
    .replace(/\/trace\/[^/?#]+/i, `/sessions/${senderId}`);
};

export const LangfuseSessionButton = ({
  conversationList,
  sessionId,
}: LangfuseSessionButtonProps) => {
  const activeConversation =
    conversationList.find((c) => c.id === sessionId) || conversationList.at(-1);
  const latestEventWithLangfuse = activeConversation?.events
    ?.slice()
    .reverse()
    .find((event) =>
      Boolean(event.metadata?.langfuse_session_url || event.metadata?.langfuse_trace_url),
    );
  const sessionTraceUrl =
    latestEventWithLangfuse?.metadata?.langfuse_session_url ||
    deriveSessionUrlFromTraceUrl(latestEventWithLangfuse?.metadata?.langfuse_trace_url, sessionId);

  const tooltipContent = useMemo(
    () =>
      sessionTraceUrl ? (
        "Open Langfuse session"
      ) : (
        <Box>
          Langfuse is currently not configured for this agent. Once setup is complete, you can open
          this session in Langfuse.{" "}
          <Link
            href={LANGFUSE_DOCS_URL}
            color="white"
            textDecoration="underline"
            target="_blank"
            rel="noopener noreferrer"
          >
            View Docs
          </Link>
        </Box>
      ),
    [sessionTraceUrl],
  );

  return (
    <Tooltip content={tooltipContent} showArrow interactive={true} closeDelay={200}>
      <Box>
        {sessionTraceUrl ? (
          <IconButton
            asChild
            aria-label="Open Langfuse session"
            data-testid="open-langfuse-session"
            variant="ghost"
            size="sm"
          >
            <a href={sessionTraceUrl} target="_blank" rel="noopener noreferrer">
              <Icon icon={ExternalLink} />
            </a>
          </IconButton>
        ) : (
          <IconButton
            aria-label="Open Langfuse session"
            data-testid="open-langfuse-session"
            variant="ghost"
            size="sm"
            disabled
          >
            <Icon icon={ExternalLink} />
          </IconButton>
        )}
      </Box>
    </Tooltip>
  );
};
